#include "stdlib/blas/base/sgemv.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/sscal.h"
#include "stdlib/blas/ext/base/sfill.h"
#include "stdlib/ndarray/base/assert/is_row_major.h"

/**
* Performs one of the matrix-vector operations `y = α*A*x + β*y` or `y = α*A^T*x + β*y` using alternative indexing semantics, where `α` and `β` are scalars, `x` and `y` are vectors, and `A` is an `M` by `N` matrix.
*
* @param trans     specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param M         number of rows in the matrix `A`
* @param N         number of columns in the matrix `A`
* @param alpha     scalar constant
* @param A         input matrix
* @param strideA1  stride of the first dimension of `A`
* @param strideA1  stride of the second dimension of `A`
* @param offsetA   starting index for `A`
* @param x         first input vector
* @param strideX   `x` stride length
* @param offsetX   starting index for `x`
* @param beta      scalar constant
* @param y         second input vector
* @param strideY   `y` stride length
* @param offsetY   starting index for `Y`
* @return          output value
*/
void API_SUFFIX(c_sgemv_ndarray)( const CBLAS_TRANSPOSE trans, const CBLAS_INT M, const CBLAS_INT N, const float alpha, const float *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, const float *x, const CBLAS_INT strideX, const CBLAS_INT offsetX, const float beta, float *y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
	CBLAS_INT isrm;
	CBLAS_INT xlen;
	CBLAS_INT ylen;
	CBLAS_INT ix1;
	CBLAS_INT iy1;
	CBLAS_INT sa0;
	CBLAS_INT sa1;
	CBLAS_INT i0;
	CBLAS_INT i1;
	CBLAS_INT oa;
	float tmp;

	// Note on variable naming convention: sa#, ix#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	int64_t strides[] = { strideA1, strideA2 };
	isrm = stdlib_ndarray_is_row_major( 2, strides );
	
	if ( M == 0 || N == 0 || ( alpha == 0.0f && beta == 1.0f ) ) {
		return;
	}
	if ( isrm ) {
		sa0 = strideA2;
		sa1 = strideA1;
	} else {
		sa0 = strideA1;
		sa1 = strideA2;
	}

	if ( trans == CblasNoTrans ) {
		xlen = N;
		ylen = M;
	} else {
		xlen = M;
		ylen = N;
	}

	// y = beta * y
	if ( beta != 1.0f ) {
		if ( beta == 0.0f ) {
			stdlib_strided_sfill_ndarray( ylen, 0.0f, y, strideY, offsetY );
		} else {
			c_sscal_ndarray( ylen, beta, y, strideY, offsetY );
		}
	}
	if ( alpha == 0.0f ) {
		return;
	}
	// Form: y = α*A*x + y
	if ( ( !isrm && trans == CblasNoTrans ) || ( isrm && trans != CblasNoTrans ) ) {
		ix1 = offsetX;
		for ( i1 = 0; i1 < xlen; i1++ ) {
			tmp = alpha * x[ ix1 ];
			oa = offsetA + sa1 * i1;
			iy1 = offsetY;
			for ( i0 = 0; i0 < ylen; i0++ ) {
				y[ iy1 ] += A[ oa + sa0 * i0 ] * tmp;
				iy1 += strideY;
			}
			ix1 += strideX;
		}
		return;
	}
	// Form: y = α*A^T*x + y

	// ( !isrm && trans !== 'no-transpose' ) || ( isrm && trans === 'no-transpose' )
	iy1 = offsetY;
	for ( i1 = 0; i1 < ylen; i1++ ) {
		tmp = 0.0f;
		ix1 = offsetX;
		oa = offsetA + sa1 * i1;
		for ( i0 = 0; i0 < xlen; i0++ ) {
			tmp += A[ oa + sa0 * i0 ] * x[ ix1 ];
			ix1 += strideX;
		}
		y[ iy1 ] += alpha * tmp;
		iy1 += strideY;
	}
	return;
}
